<template>
  <view class="mpb-page"><view class="mpb-safe" /><view class="mpb-header"><button class="mpb-back" aria-label="返回" @click="backOrHome('/pages/operation/OperationAgentsPage')">‹</button><image class="mpb-logo" :src="loginLogo" mode="aspectFit" /><view class="mpb-header-copy"><text class="mpb-title">代理商详情</text><text class="mpb-subtitle">团队身份与经营数据</text></view><text class="mpb-role operation">运营中心</text></view><view class="mpb-stack"><view v-if="loading" class="mpb-card mpb-empty"><text class="mpb-empty-title">正在加载代理商...</text></view><template v-else-if="item"><view class="mpb-hero"><view class="mpb-hero-top"><view><text class="mpb-hero-label">代理商</text><text class="mpb-hero-value">{{ rowString(item, 'name', 'email') }}</text></view><text class="mpb-hero-badge success">{{ statusText(rowString(item, 'status')) }}</text></view><text class="mpb-hero-copy">{{ rowString(item, 'email') || '暂无邮箱' }}</text></view><view class="mpb-card mpb-list"><view class="mpb-row"><text class="mpb-row-icon">级</text><view class="mpb-row-main"><text class="mpb-row-title">代理等级</text><text class="mpb-row-meta">{{ rowString(item, 'levelLabel', 'levelName') || `L${rowNumber(item, 'level') || 1}` }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon green">码</text><view class="mpb-row-main"><text class="mpb-row-title">邀请码</text><text class="mpb-row-meta">{{ rowString(item, 'inviteCode') || '-' }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon orange">客</text><view class="mpb-row-main"><text class="mpb-row-title">直属客户</text><text class="mpb-row-meta">运营中心接口统计</text></view><text class="mpb-amount">{{ formatNumber(rowNumber(item, 'directCustomers', 'customerCount')) }}</text></view></view></template><view v-else class="mpb-card mpb-empty"><text class="mpb-empty-title">未找到代理商</text></view></view></view>
</template>
<script setup lang="ts">
import { ref } from "vue"; import { onLoad } from "@dcloudio/uni-app"; import { api } from "../../api/client"; import { asRecord, backOrHome, formatNumber, rowNumber, rowString, statusText, type AnyRecord } from "../../utils/miniProgramBusiness"; import loginLogo from "../../assets/zhiqiyun-logo-transparent.png";
const id=ref(""); const loading=ref(false); const item=ref<AnyRecord|null>(null); async function load(){loading.value=true;try{const payload=asRecord(await api(`/api/v1/operation-center/agents/${encodeURIComponent(id.value)}`));const detail=asRecord(payload.item);item.value=rowString(detail,"id","agentId")?detail:null;}catch(error){uni.showToast({title:error instanceof Error?error.message:"代理商加载失败",icon:"none"});}finally{loading.value=false;}} onLoad(options=>{id.value=String(options?.id||"");void load();});
</script>
<style>@import "../../styles/mini-program-business.css";</style>
